{{if skill "add_logging"}}    if err := logging.Configure(os.Stdout); err != nil { log.Fatal("logging initialization failed") }
    defer logging.Close()
{{end}}{{if skill "add_database"}}    if dsn := os.Getenv("DATABASE_DSN"); dsn != "" {
